# الشهر الكامل (30 يوم عمل) لدوري المبيعات ونجاح العملاء، بنظام التدوير بين الإدارات:
#   الأسبوع 1: تهيئة · الأسبوع 2: إدارتك · الأسبوع 3 و4: تدوير في إدارتين أخريين · الأسبوع 5 و6: إدارتك (مستوى أعلى)
# الفكرة: حتى من اختار إدارة بعينها يمر بالإدارات الأخرى ليفهم أجواءها وطريقة عملها، ويبني علاقات فيها.
# ═══════════════════════════════════════════════════════════════════════════
by = lambda lst: {e['id']: e for e in lst}
S, C = by(sales), by(cs)

def at(e, day, due=2, **over):
    e = copy.deepcopy(e); e['day'] = day; e['dueInDays'] = due
    for k in ('delegable', 'minDay', 'weight', 'condition'): e.pop(k, None)
    e.update(over)
    return e

def swap(e, mapping):
    """نسخة من حدث مع استبدال نصوص ومعرّفات (لتكييف أحداث التهيئة مع مدير كل دور)."""
    s = json.dumps(e, ensure_ascii=False)
    for a, b in mapping: s = s.replace(a, b)
    return json.loads(s)

def note(i, day, frm, title, body, attachments=None):
    e = {"id": i, "day": day, "type": "message", "from": frm, "priority": "normal", "dueInDays": 2, "skills": ["communication"], "title": title, "body": body,
         "options": [{"id": "ok", "label": "علم", "quality": 0.8, "effects": [T(frm, 1)]}]}
    if attachments: e["attachments"] = attachments
    return e

def onboarding(mgr, mgr_name, dept):
    m = [('"cpo"', f'"{mgr}"'), ('خالد', mgr_name), ('فريق المنتجات', dept)]
    kick = {"id": "d1_kickoff", "day": 1, "type": "meeting", "from": mgr, "priority": "normal", "dueInDays": 1, "skills": ["communication", "people"],
        "title": "اجتماع الفريق — 10:00", "body": f"اجتماع تعارف مع {dept}. استمع أكثر مما تتكلم في يومك الأول.",
        "options": [opt('listen_ask', 'استمع واسأل عن الأهداف والعوائق الحالية', 0.9, [T(mgr, 4), T('mentor', 2)], 'الفريق شعر أنك تريد أن تفهم قبل أن تقرر.'),
                    opt('pitch_ideas', 'اعرض أفكارك الكبيرة من اليوم الأول', 0.4, [T(mgr, -3)], f'{mgr_name}: لنفهم الوضع أولًا.', 'bad')]}
    return [swap(at(ev['d1_welcome'], 1, 1), m), at(ev['d1_handbook'], 1, 2), at(ev['d1_mentor_check'], 1, 2), kick, at(ev['d2_kpi_tour'], 2, 2)]

def rotation_note(i, day, frm, dept, host_name, why):
    return note(i, day, frm, f"FYI: تدويرك هذا الأسبوع في {dept}",
        f"هذا الأسبوع تعمل مع {dept} ضمن برنامج التدوير بين الإدارات. {why} مضيفك هناك {host_name}. نصيحة: احجز جلسة تعارف مع اثنين من الفريق على الأقل من صفحة «فريقي»، فالعلاقات التي تبنيها الآن تنفعك حين تعود.")

